#include <stdio.h>
#include <stdlib.h>

static int clamp(int v) {
    if (v < 0) {
        return 0;
    } else if (v > 255) {
        return 255;
    } else if (v > 127) {
        return v - 1;
    }
    return v;
}

int run(int n) {
    if (n) goto done;
    n = clamp(n);
done:
    return n;
}

